package com.shopsphere;import java.util.*;import java.util.concurrent.ConcurrentHashMap;public interface OrderRepository{Order save(Order o);Optional<Order>find(UUID id);List<Order>findByUser(UUID user);List<Order>findAll(int page,int size);class InMemory implements OrderRepository{private final Map<UUID,Order>data=new ConcurrentHashMap<>();public List<Order>findAll(int page,int size){return data.values().stream().sorted(Comparator.comparing(Order::createdAt).reversed()).skip((long)Math.max(page,0)*size).limit(size).toList();}public Order save(Order o){data.put(o.id(),o);return o;}public Optional<Order>find(UUID id){return Optional.ofNullable(data.get(id));}public List<Order>findByUser(UUID u){return data.values().stream().filter(o->o.userId().equals(u)).sorted(Comparator.comparing(Order::createdAt).reversed()).toList();}}}
